type dispatcherEventUpdated struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventUpdated) Dispatch(e dpapp.EventUpdated) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventUpdated) DispatchCtx(
	ctx context.Context, e dpapp.EventUpdated,
) error {
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventUpdated JSON: %w", err)
	}
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, EvSubjUpdated, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", EvSubjUpdated, err)
	}
	return nil
}

